-- 0078 — CAT : import des marques et modèles déclarés à la douane (suite d'US-113 ; ADR-109,
-- ADR-094 ; 17 §3.2.3, ADR-034 ; 22 OQ-CAT-01). Appliquée sous `migrator`, en une transaction.
-- Expand seulement (ADR-081) : une valeur de source de plus, des colonnes rendues facultatives,
-- deux contraintes ajoutées, des lignes insérées ; aucune ligne existante n'est modifiée.
--
-- Principes (ADR-109, PROPOSÉS) :
--   - source `DNIT_ADUANAS_PY` : données ouvertes de la DNIT – Gerencia General de Aduanas,
--     « Licencia de Uso de la Información Pública del Gobierno Paraguayo » (source et date de mise
--     à jour citées, aucun aval officiel suggéré) ; chaque ligne porte source et license_note ;
--   - la douane ne donne AUCUNE caractéristique technique : carrosserie, places et portes du modèle,
--     boîte, carburant, transmission, places et portes de la variante deviennent facultatives, mais
--     seulement pour cette source (contraintes `*_specs_complete`) ; toute autre source reste tenue
--     de fournir sa fiche, comme en 0063 ; rien n'est deviné, l'ops complète ;
--   - la graine v1 (0063) garde ses lignes et sa provenance : un modèle déjà présent n'est jamais
--     recréé, il ne reçoit qu'une variante sans fiche pour des années antérieures à ses variantes ;
--   - variantes sans fiche du marché de la source (`market`), années indicatives ; lignes ACTIVE,
--     non vérifiées (`verified_by` nul), choisissables par l'hôte : l'annonce passe la revue de
--     l'ops (US-118) ;
--   - la graine ci-dessous est GÉNÉRÉE depuis apps/api/src/modules/cat/data/vehicle-catalog-dnit.json
--     par apps/api/src/modules/cat/internal/vehicle-catalog/customs-import.ts, qui refuse une ligne
--     sans source, sans licence validée ou en doublon de la v1 ; customs-import.test.ts compare.
--   - preuves sous migrator : test-migrations/9981_test_us113_customs_fixtures.sql ; sous les
--     rôles de production : test/l0/l0-us113-customs-import.test.ts.
--
-- Retour arrière (aucune ligne d'hôte ne doit référencer une variante de la douane) : retirer les
-- lignes par `status = 'RETIRED'` (jamais de DELETE, garde de 0063) ; les contraintes élargies
-- restent compatibles avec la version précédente.

-- 1. Nouvelle valeur de source (CHECK remplacé sous le même nom, strictement plus large) ----------
ALTER TABLE core.catalog_vehicle_make
  DROP CONSTRAINT catalog_vehicle_make_source_check,
  ADD CONSTRAINT catalog_vehicle_make_source_check
    CHECK (source IN ('WIKIDATA', 'NHTSA_VPIC', 'OPS_CURATED', 'HOST_REQUEST', 'DNIT_ADUANAS_PY'));
ALTER TABLE core.catalog_vehicle_model
  DROP CONSTRAINT catalog_vehicle_model_source_check,
  ADD CONSTRAINT catalog_vehicle_model_source_check
    CHECK (source IN ('WIKIDATA', 'NHTSA_VPIC', 'OPS_CURATED', 'HOST_REQUEST', 'DNIT_ADUANAS_PY'));
ALTER TABLE core.catalog_vehicle_variant
  DROP CONSTRAINT catalog_vehicle_variant_source_check,
  ADD CONSTRAINT catalog_vehicle_variant_source_check
    CHECK (source IN ('WIKIDATA', 'NHTSA_VPIC', 'OPS_CURATED', 'HOST_REQUEST', 'DNIT_ADUANAS_PY'));

-- 2. Fiche technique facultative pour la seule source sans fiche (douane) ----------------------
-- Les CHECK de valeur de 0063 restent (une valeur présente est toujours valide).
ALTER TABLE core.catalog_vehicle_model
  ALTER COLUMN body_type DROP NOT NULL,
  ALTER COLUMN seats_default DROP NOT NULL,
  ALTER COLUMN doors_default DROP NOT NULL,
  ADD CONSTRAINT catalog_vehicle_model_specs_complete
    CHECK (source = 'DNIT_ADUANAS_PY'
           OR (body_type IS NOT NULL AND seats_default IS NOT NULL AND doors_default IS NOT NULL));
ALTER TABLE core.catalog_vehicle_variant
  ALTER COLUMN transmission DROP NOT NULL,
  ALTER COLUMN fuel_type DROP NOT NULL,
  ALTER COLUMN drive DROP NOT NULL,
  ALTER COLUMN seats DROP NOT NULL,
  ALTER COLUMN doors DROP NOT NULL,
  ADD CONSTRAINT catalog_vehicle_variant_specs_complete
    CHECK (source = 'DNIT_ADUANAS_PY'
           OR (transmission IS NOT NULL AND fuel_type IS NOT NULL AND drive IS NOT NULL
               AND seats IS NOT NULL AND doors IS NOT NULL));

COMMENT ON COLUMN core.catalog_vehicle_model.body_type IS
  'Carrosserie (17 §3.2.3) ; NULL seulement pour une source sans fiche (DNIT_ADUANAS_PY, ADR-109) : '
  'à compléter par l''ops.';
COMMENT ON COLUMN core.catalog_vehicle_variant.transmission IS
  'Boîte (17 §3.2.3) ; NULL, comme carburant, transmission, places et portes, seulement pour une '
  'source sans fiche (DNIT_ADUANAS_PY, ADR-109) : à compléter par l''ops, saisi par l''hôte.';

-- 3. Graine de la douane (PROPOSÉE, ADR-109) : rendue depuis les données, une instruction par table
